function get(k,f){try{const x=JSON.parse(localStorage.getItem(k));return x===null?f:x}catch{return f}}
function put(k,v){localStorage.setItem(k,JSON.stringify(v))}
function clearOldAuthSession(){for(let i=localStorage.length-1;i>=0;i--){const key=localStorage.key(i);if(/^sb-[a-z0-9-]+-auth-token$/i.test(key||''))localStorage.removeItem(key)}}
function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function keyDate(d){return d.getFullYear()+'-'+('0'+(d.getMonth()+1)).slice(-2)+'-'+('0'+d.getDate()).slice(-2)}
function dateOf(s){return new Date(s+'T12:00:00')}
function todayKey(){return keyDate(new Date())}
function attemptById(id){return ATTEMPTS.find(x=>x.id===id)||ATTEMPTS[0]}
function attemptEnd(a){if(a.end)return a.end;const p=a.month.split('-').map(Number);return keyDate(new Date(p[0],p[1],0))}
