function hashDay(d){return Math.floor((dateOf(d)-dateOf('2026-01-01'))/86400000)}
function subjectForDay(d){const n=((hashDay(d)%4)+4)%4;return SUBJECTS[n]}
function shiftTime(v,minutes){const a=(v||'05:00').split(':').map(Number),n=(a[0]*60+a[1]+minutes+1440*3)%1440;return ('0'+Math.floor(n/60)).slice(-2)+':'+('0'+(n%60)).slice(-2)}
function range(start,minutes){return start+'–'+shiftTime(start,minutes)}
function formatHours(h){return Number.isInteger(+h)?h+' h':(+h).toFixed(1)+' h'}
function tickWindow(d,t){const value=String(t&&t.time||''),parts=x=>x.split(':').map(Number),valid=a=>a[0]<=23&&a[1]<=59;if(t&&t.id==='morning-reset'){const m=value.match(/^(\d{1,2}:\d{2})$/);if(m){const a=parts(m[1]);if(valid(a)){const start=dateOf(d);start.setHours(a[0],a[1],0,0);const deadline=new Date(start.getTime()+15*60000),now=new Date(),state=now<start?'upcoming':now<deadline?'available':'closed';return {timed:true,allowed:state==='available',state,start:start,end:start,deadline,kind:'wake'}}}}const m=value.match(/(\d{1,2}:\d{2})\s*[–-]\s*(\d{1,2}:\d{2})/);if(!m)return {timed:false,allowed:true,state:'untimed',kind:'untimed'};const a=parts(m[1]),b=parts(m[2]);if(!valid(a)||!valid(b))return {timed:false,allowed:true,state:'untimed',kind:'untimed'};const start=dateOf(d),end=dateOf(d);start.setHours(a[0],a[1],0,0);end.setHours(b[0],b[1],0,0);if(end<=start)end.setDate(end.getDate()+1);const deadline=new Date(end.getTime()+15*60000),now=new Date(),state=now<start?'upcoming':now<deadline?'available':'closed';return {timed:true,allowed:state==='available',state,start,end,deadline,kind:'range'}}
function tickHint(w,done){if(done)return '✓ Completed';if(!w||!w.timed)return '';const time=d=>d.toLocaleTimeString([],{hour:'numeric',minute:'2-digit'});if(w.state==='available')return '✓ Available to tick now · closes at '+time(w.deadline);if(w.state==='upcoming')return '× Unavailable · opens at '+time(w.start);return '× Unavailable · time ended at '+time(w.deadline)}
function clockLabel(d){return d.toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}
function gapLabel(n){const h=Math.floor(n/60),m=n%60;return (h?h+' h ':'')+(m?m+' min':h?'':'0 min')}
function breaksBefore(d,tasks){const timed=tasks.map(t=>({task:t,window:tickWindow(d,t)})).filter(x=>x.window.kind==='range').sort((a,b)=>a.window.start-b.window.start),out={};for(let i=1;i<timed.length;i++){const prev=timed[i-1],next=timed[i],mins=Math.floor((next.window.start-prev.window.end)/60000);if(mins>=10)out[next.task.id]='<div class="breakBlock" aria-label="Non-clickable break from '+clockLabel(prev.window.end)+' to '+clockLabel(next.window.start)+'"><span>RESET WINDOW · NO TICK</span><strong>Break · '+gapLabel(mins)+'</strong><small>'+clockLabel(prev.window.end)+'–'+clockLabel(next.window.start)+' · Rest, pray or hydrate.</small></div>'}return out}function durationMinutes(t){const m=String(t&&t.time||'').match(/(\d{1,2}:\d{2})\s*[–-]\s*(\d{1,2}:\d{2})/);if(!m)return 0;const a=m[1].split(':').map(Number),b=m[2].split(':').map(Number);let n=(b[0]*60+b[1])-(a[0]*60+a[1]);if(n<=0)n+=1440;return n}
function studyMinutes(d){const p=planFor(d),c=checksFor(d);return (p.tasks||[]).filter(t=>t.id.startsWith('study-')&&c[t.id]).reduce((n,t)=>n+durationMinutes(t),0)}
