function migrate(){let p=get(K.profile,null);if(p){if(p.commuteTo==null)p.commuteTo=p.commute==null?105:+p.commute;if(p.commuteFrom==null)p.commuteFrom=p.commute==null?105:+p.commute;const historyStart=Array.from({length:localStorage.length},(_,i)=>localStorage.key(i)).filter(k=>k&&k.startsWith(K.checks)).map(k=>k.slice(K.checks.length)).filter(d=>/^\d{4}-\d{2}-\d{2}$/.test(d)&&d<=todayKey()).sort()[0];if(historyStart&&(!p.plannerStartDate||historyStart<p.plannerStartDate))p.plannerStartDate=historyStart;if(!p.plannerStartDate)p.plannerStartDate=todayKey();delete p.commute;put(K.profile,p);return p}const old=get(OLD.profile,null);if(!old)return null;p=Object.assign(profileDefault(),old);p.attemptId='jan-2027';p.studyHours=Math.min(12,Math.max(2,+old.hours||8));p.campusHours=Math.min(4,Math.max(1,+old.hours||2));p.commuteTo=p.commuteFrom=old.commute==null?105:+old.commute;delete p.commute;p.faith=old.prayers===false?'none':'muslim';put(K.profile,p);const chapters=get(OLD.chapter,null);if(chapters)put(K.chapter,chapters);return p}
