function getOverrides(){return get(K.dayTypes,{})}
function getDayKind(d){const exam=getExam(d);if(exam&&exam.attempt===profile.attemptId)return 'exam';const overrides=getOverrides();if(overrides[d])return overrides[d];if(new Date(d+'T12:00:00').getDay()===0)return 'sunday';if(d>=(profile.leaveDate||defaultLeaveDate(attemptById(profile.attemptId))))return 'study';const wd=dateOf(d).getDay();if((profile.campusDays||[]).includes(wd))return 'campus';return 'self-study'}
function task(id,time,title,desc){return {id:id,time:time,title:title,desc:desc}}
function minutesAt(v){const a=(v||'00:00').split(':').map(Number);return a[0]*60+a[1]}
function timeGap(start,end){return Math.max(0,minutesAt(end)-minutesAt(start))}
function dailyTargetHours(d){const k=getDayKind(d);if(k==='campus')return +profile.campusHours||0;if(k==='sunday')return +profile.sundayHours||0;if(k==='exam')return 0;return +profile.studyHours||0}
