function renderPractice(){if(!$('quizQuestions'))return;const scope=$('quizSubject').value||'today',q=getQuiz(scope),items=q.ids.map(id=>QUESTION_BY_ID.get(id)).filter(Boolean);$('quizQuestions').innerHTML=items.map((x,n)=>'<article class="quizCard"><div class="eyebrow">'+esc(SUBJECTS.find(s=>s.id===x.s).name+' · '+x.topic)+(x.type==='written'?' · written response':' · MCQ')+'</div><h3>'+(n+1)+'. '+esc(x.q)+'</h3>'+(x.type==='written'?'<textarea class="writtenAnswer" data-answer="'+esc(x.id)+'" rows="5" placeholder="Write your answer here…" '+(q.submitted?'readonly':'')+'>'+esc(q.answers[x.id]||'')+'</textarea>'+(q.submitted?'<details class="answerGuide" open><summary>Answer guide</summary><p>'+esc(x.e)+'</p></details>':''):'<div class="quizOptions">'+x.o.map((o,i)=>'<label class="'+(Object.prototype.hasOwnProperty.call(q.answers,x.id)?(i===x.a?'answer-correct':(+q.answers[x.id]===i?'answer-incorrect':'')):'')+'"><input type="radio" name="answer-'+x.id+'" value="'+i+'" '+(+q.answers[x.id]===i?'checked':'')+' '+(q.submitted?'disabled':'')+'><span>'+esc(o)+'</span></label>').join('')+'</div>'+(q.submitted||Object.prototype.hasOwnProperty.call(q.answers,x.id)?'<div class="feedback '+(+q.answers[x.id]===x.a?'correct':'incorrect')+'">'+(+q.answers[x.id]===x.a?'Correct. ':'Review. ')+esc(x.e)+'</div>':''))+'</article>').join('');
 const score=items.filter(x=>x.type==='mcq'&&+q.answers[x.id]===x.a).length,mcqCount=items.filter(x=>x.type==='mcq').length;$('quizNotice').textContent=q.submitted?(mcqCount?'Score: '+score+' / '+mcqCount+' MCQs':'Written responses saved · compare them with each answer guide')+' · Saved in this browser.':'10,000 generated MCQs are available for each subject, plus original questions. Answers and explanations appear as soon as you choose an option.'+(scope==='today'?' Today’s set follows your assigned chapter portions.':'')+' Saved in this browser.';$('checkQuiz').textContent=q.submitted?'Review complete set':'Finish set · view score';$('checkQuiz').disabled=q.submitted;
 document.querySelectorAll('.quizOptions input').forEach(el=>el.onchange=()=>{const id=el.name.replace('answer-',''),n=get(quizKey(scope),q);n.answers[id]=+el.value;put(quizKey(scope),n);const item=QUESTION_BY_ID.get(id),card=el.closest('.quizCard'),correct=+el.value===item.a;let feedback=card.querySelector('.instantFeedback');if(!feedback){feedback=document.createElement('div');feedback.className='feedback instantFeedback';card.appendChild(feedback)}feedback.className='feedback instantFeedback '+(correct?'correct':'incorrect');feedback.textContent=(correct?'Correct. ':'Not quite. ')+item.e;card.querySelectorAll('.quizOptions label').forEach((label,index)=>{label.classList.toggle('answer-correct',index===item.a);label.classList.toggle('answer-incorrect',index===+el.value&&!correct)})});
 document.querySelectorAll('[data-answer]').forEach(el=>el.oninput=()=>{const n=get(quizKey(scope),q);n.answers[el.dataset.answer]=el.value;put(quizKey(scope),n)});
}
if($('quizSubject'))$('quizSubject').onchange=renderPractice;
if($('newQuiz'))$('newQuiz').onclick=()=>{const scope=$('quizSubject').value||'today';put(quizKey(scope),{ids:sampleQuestions(scope),answers:{},submitted:false,focusStamp:questionFocusStamp(scope)});renderPractice()};
if($('checkQuiz'))$('checkQuiz').onclick=()=>{const scope=$('quizSubject').value||'today',q=getQuiz(scope);if(!q.ids.every(id=>id in q.answers&&(QUESTION_BY_ID.get(id).type!=='written'||String(q.answers[id]).trim()))){$('quizNotice').textContent='Answer every question before saving this set.';return}q.submitted=true;put(quizKey(scope),q);const d=todayKey();setCheck(d,'daily-practice',true);renderPractice();renderTasks();renderProgress()};
function renderProgress(){
 const ch=get(K.chapter,{}),total=SUBJECTS.reduce((n,s)=>n+s.chapters.length,0),done=SUBJECTS.reduce((n,s)=>n+s.chapters.filter((_,i)=>ch[s.id+'-'+i]==='revised').length,0),tracked=Object.keys(localStorage).filter(k=>k.startsWith(K.checks)&&Object.values(get(k,{})).some(Boolean)).length;
 $('completePct').textContent=Math.round(done/total*100)+'%';$('trackedDays').textContent=tracked;$('targetHours').textContent=formatHours(profile.studyHours)+' / '+formatHours(profile.campusHours);updateCountdown();
 const mins=studyMinutes(todayKey()),target=dailyTargetHours(todayKey())*60;$('hoursToday').textContent=formatHours(Math.round(mins/6)/10);$('hoursTodayLabel').textContent=formatHours(profile.studyHours)+' target · '+Math.round(mins)+' min from completed study blocks';
 const keys=Array.from({length:7},(_,i)=>addDaysKey(todayKey(),i-6)),values=keys.map(d=>studyMinutes(d)/60),max=Math.max(1,...values,+profile.studyHours||1);
 $('hourChart').innerHTML=keys.map((d,i)=>'<div class="hourBarWrap" title="'+esc(d+' · '+formatHours(values[i]))+'"><div class="hourBarArea"><i style="height:'+Math.max(values[i]?5:0,Math.round(values[i]/max*100))+'%"></i></div><span>'+dateOf(d).toLocaleDateString(undefined,{weekday:'short'})+'</span><b>'+formatHours(Math.round(values[i]*10)/10)+'</b></div>').join('')
}
function renderMotivationQuote(){const quoteEl=$('dailyQuote'),authorEl=$('dailyQuoteAuthor');if(!quoteEl||!MOTIVATION_QUOTES.length)return;const key='aethel-motivation-quote-v1-'+todayKey();let index=get(key,null);if(!Number.isInteger(index)||index<0||index>=MOTIVATION_QUOTES.length){index=Math.floor(Math.random()*MOTIVATION_QUOTES.length);put(key,index)}const draw=()=>{const item=MOTIVATION_QUOTES[index];quoteEl.textContent='“'+item.text+'”';authorEl.textContent=item.author?'— '+item.author:'';authorEl.classList.toggle('hidden',!item.author)};draw();const button=$('quoteRefresh');if(button)button.onclick=()=>{index=(index+1+Math.floor(Math.random()*(MOTIVATION_QUOTES.length-1)))%MOTIVATION_QUOTES.length;put(key,index);draw()}}
function render(){if(!profile)return;const n=daysLeft(),p=phase(),todayPlan=planFor(todayKey()),a=attemptById(profile.attemptId),w=sprintWindow(a);$('welcome').textContent='Welcome, '+(profile.studentName||'student')+'.';$('subline').textContent='A steady plan, built around your real week.';$('todayTitle').textContent=new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'});$('todayIntro').textContent=(todayPlan.kind==='exam'?'Today is '+(todayPlan.exam?todayPlan.exam.title:'an exam day'):todayPlan.kind==='campus'?'Campus day · '+formatHours(profile.campusHours)+' focused self-study · outbound '+(profile.commuteTo||0)+' min · return '+(profile.commuteFrom||0)+' min':'Study target '+formatHours(todayPlan.kind==='sunday'?profile.sundayHours:profile.studyHours))+' · '+a.name+'.';if($('todayDayKind')){$('todayDayKind').value=todayPlan.kind==='exam'?'exam':(getOverrides()[todayKey()]||'auto');$('todayDayKind').disabled=todayPlan.kind==='exam'}$('phaseNow').textContent=p.title+' — '+p.text;$('phases').innerHTML='<div class="notice"><b>1 · Coverage and foundations</b><br>Use the daily ICAI material checklist for first-pass learning; mark each chapter’s progress in the tracker.</div><div class="notice"><b>2 · 16-day syllabus completion sprint · '+dateOf(w.start).toLocaleDateString(undefined,{day:'numeric',month:'short'})+'–'+dateOf(w.end).toLocaleDateString(undefined,{day:'numeric',month:'short'})+'</b><br>Follow the date-by-date chapter map below. The last day is the day before the first scheduled paper.</div><div class="notice"><b>3 · Paper-by-paper revision</b><br>Between announced papers, use the next paper’s ICAI RTP/MTP, error log and a short recap; follow the final subject/date on your admit card.</div><div class="notice">'+(a.published?'January 2027 exam dates are from ICAI’s published schedule. Paper/date details should be checked against the admit card.':'ICAI has not published exact dates for '+esc(a.name)+' yet; sprint dates use a provisional month-end planning anchor.')+'</div>';updateCountdown();renderTasks();renderProgress();renderMotivationQuote();renderSyllabus();renderFacultyCoverage();renderPractice();renderSprint();renderDoubts();if($('practiceResources'))$('practiceResources').innerHTML=renderResources();const calendarStart=(profile.plannerStartDate||todayKey())<=attemptEnd(a)?(profile.plannerStartDate||todayKey()):attemptEnd(a),query='start='+calendarStart+'&attempt='+encodeURIComponent(profile.attemptId)+'&end='+attemptEnd(a),url='calendar.html?'+query;if(!$('calendarFrame').src.endsWith(url))$('calendarFrame').src=url}
function notifyCalendar(type,data){const f=$('calendarFrame');if(f&&f.contentWindow)f.contentWindow.postMessage(Object.assign({type:type},data||{}),location.origin)}
window.addEventListener('message',e=>{if(e.origin!==location.origin||!$('calendarFrame')||e.source!==$('calendarFrame').contentWindow||!e.data)return;const m=e.data;if(m.type==='aethel-check-change'){if(m.date!==todayKey())return;const p=planFor(m.date),task=p.tasks.find(x=>x.id===m.id);if(!task)return;const gate=tickWindow(m.date,task);if(gate.timed&&!gate.allowed)return;const c=checksFor(m.date);c[m.id]=!!m.value;put(K.checks+m.date,c);if(m.id.startsWith('portion-'))updateChapterFromPortion(m.id,!!m.value);renderTasks();renderProgress();renderSyllabus()}else if(m.type==='aethel-open-today'){const todayTab=document.querySelector('.tabs button[data-page="today"]');if(todayTab)todayTab.click()}else if(m.type==='aethel-daytype-change'){put(K.dayTypes,getOverrides());ensurePlans();render();notifyCalendar('aethel-storage-updated')}});
window.addEventListener('storage',e=>{const key=e.key;if(!key||!profile)return;if(key.startsWith(K.checks)){put(key,get(key,{}));renderTasks();renderProgress();renderSyllabus();return}if(key===K.chapter){put(key,get(key,{}));renderSyllabus();renderTasks();renderProgress();return}if(key===K.faculty){put(key,get(key,{}));renderFacultyCoverage();return}if(key===K.dayTypes){put(key,get(key,{}));ensurePlans();render();notifyCalendar('aethel-storage-updated');return}if(key.startsWith(K.plans)){put(key,get(key,null));if(key===planKey(todayKey())){renderTasks();renderProgress()}notifyCalendar('aethel-storage-updated')}});
function doubts(){return get(K.doubts,[])}
function renderDoubts(){if(!$('doubtList'))return;const items=doubts().slice().sort((a,b)=>b.createdAt-a.createdAt);$('doubtList').innerHTML=items.length?items.map(x=>'<article class="doubtCard '+(x.cleared?'cleared':'')+'"><div class="doubtTop"><div><span class="doubtStatus">'+(x.cleared?'Doubt cleared':'Needs follow-up')+'</span><h3>'+esc(x.topic)+'</h3></div><button class="btn '+(x.cleared?'ghost':'alt')+'" data-clear-doubt="'+esc(x.id)+'">'+(x.cleared?'Reopen':'Doubt cleared ✓')+'</button></div><div class="small">'+esc(x.subject)+' · '+esc(x.date)+(x.source==='faculty'?' · Faculty: '+esc(x.faculty||'Not added'):' · Self-doubt')+'</div>'+(x.notes?'<p>'+esc(x.notes)+'</p>':'')+'</article>').join(''):'<div class="notice">Your doubt log is empty. Add a topic you want to revisit or ask your faculty about.</div>';document.querySelectorAll('[data-clear-doubt]').forEach(b=>b.onclick=()=>{const a=doubts(),x=a.find(d=>d.id===b.dataset.clearDoubt);if(x){x.cleared=!x.cleared;put(K.doubts,a);renderDoubts()}})}
if($('doubtDate'))$('doubtDate').value=todayKey();
if($('doubtSource'))$('doubtSource').onchange=()=>{$('facultyField').classList.toggle('hidden',$('doubtSource').value!=='faculty')};
if($('doubtForm'))$('doubtForm').onsubmit=e=>{e.preventDefault();const topic=$('doubtTopic').value.trim();if(!topic)return;const items=doubts();items.push({id:'doubt-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),source:$('doubtSource').value,faculty:$('doubtFaculty').value.trim(),subject:$('doubtSubject').value,date:$('doubtDate').value||todayKey(),topic:topic,notes:$('doubtNotes').value.trim(),cleared:false,createdAt:Date.now()});put(K.doubts,items);e.target.reset();$('doubtDate').value=todayKey();$('facultyField').classList.remove('hidden');$('doubtSource').value='faculty';renderDoubts()};
if($('todayDayKind'))$('todayDayKind').onchange=()=>{const d=todayKey(),official=getExam(d);if(official&&official.attempt===profile.attemptId)return;const m=getOverrides();if($('todayDayKind').value==='auto')delete m[d];else m[d]=$('todayDayKind').value;put(K.dayTypes,m);ensurePlans();render();notifyCalendar('aethel-storage-updated')};document.querySelectorAll('.tabs button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tabs button').forEach(x=>x.classList.toggle('on',x===b));['today','calendar','syllabus','strategy','practice','doubts','exam'].forEach(x=>$('page-'+x).classList.toggle('hidden',x!==b.dataset.page));if(b.dataset.page==='practice')renderPractice();if(b.dataset.page==='doubts')renderDoubts()});
boot();
let tickDate=todayKey();window.setInterval(()=>{if(document.visibilityState!=='visible')return;const current=todayKey();if(current!==tickDate){tickDate=current;if(profile){ensurePlans();render();notifyCalendar('aethel-storage-updated')}return}refreshTodayTickState()},15000);




